<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>{{ $document['receipt_number'] }}</title><style>body{font-family:"DejaVu Sans",sans-serif;margin:30px;color:#25352f;font-size:12px;line-height:1.8}h1{color:#1f594e;font-size:30px}.amount{font-size:26px;font-weight:bold;padding:20px;background:#edf3ef}table{width:100%;margin:28px 0}td{padding:8px;border-bottom:1px solid #dae3dd}</style></head><body><h1>PAYMENT RECEIPT</h1><h2>{{ $document['business']['legal_name'] ?? $document['business']['name'] ?? '' }}</h2><div>{{ $document['business']['address'] ?? '' }}</div><div>{{ $document['business']['email'] ?? '' }}</div><p>{{ $document['receipt_number'] }}<br>Received {{ substr($document['settled_at'],0,10) }}</p><h2>{{ $document['customer']['name'] }}</h2><div>{{ $document['customer']['email'] ?? '' }}</div><p class="amount">{{ $document['currency'] }} {{ (new \App\Finance\Money($document['amount_minor'], $document['currency']))->format() }}</p><table><tr><td>Invoice</td><td>{{ $document['invoice_number'] }}</td></tr><tr><td>Payment method</td><td>{{ ucfirst(str_replace('_',' ',$document['method'])) }}</td></tr><tr><td>Reference</td><td>{{ $document['reference'] }}</td></tr></table><p>This receipt records the settled payment. Subsequent refunds and invoice credits appear separately in your portal.</p></body></html>
